import SwiftUI
struct FoodCardView: View { @EnvironmentObject var store:AppStore; let item:FoodItem; @State private var expanded=false; var body: some View { VStack(alignment:.leading){ HStack{ Text(item.name).font(.headline); Spacer(); Button{store.toggleFavorite(item)} label:{Image(systemName: store.favorites.contains(item.id) ? "heart.fill":"heart")}; Button("Tray"){store.addToTray(item)} } ; Text(item.servingSize ?? "Serving size n/a").font(.subheadline); if expanded { NutritionDetailView(item:item) }; Button(expanded ? "Hide Details":"Show Details"){ expanded.toggle() }.font(.caption) }.padding().background(Color.white).cornerRadius(12).shadow(radius:1).padding(.horizontal) }}
